}

```

4. Run above search request with limited composite aggregation size:3
```
POST test-activities/_search
{
  "aggs": {
    "rollup":{
      "composite": {
        "size": 3,
        "sources": [
          {
            "activityTime": {
              "date_histogram": {
                "calendar_interval": "1d",
                "field": "activityTime"
              }
            }
          },
          {
            "subscriberID": {
              "terms": {
                "field": "subscriberID",
                "missing_bucket": true
              }
            }
          }
        ]
      }
    }
  },
  "size": 0,
  "track_total_hits": false
}
```
