5. Use the after key and run below search request to get the next page:
```
POST test-activities/_search
{
  "aggs": {
    "rollup":{
      "composite": {
        "after" : {
        "activityTime" : 1591142400000,
        "subscriberID" : "31640"
        },
        "size": 3,
        "sources": [
          {
            "activityTime": {
              "date_histogram": {
                "calendar_interval": "1d",
                "field": "activityTime"
              }
            }
          },
          {
